// Hand-written service worker — not generated by vite-plugin-pwa.
//
// TanStack Start builds client/SSR/server code as three separate Vite
// "environments" in one `vite build` run. vite-plugin-pwa's generateSW hooks
// into each environment's build-end and has no notion of that split: it ran
// three times against incomplete asset lists and wrote sw.js to a bare
// top-level dist/ directory that Nitro's Vercel preset never packages —
// the service worker silently never reached the deployed static output.
//
// This file sidesteps that entirely by living in public/, which both the
// plain Vite client build and Nitro's static-asset copy already handle
// correctly (verified: public/icons/* reach .vercel/output/static/icons/*
// unchanged) — so this file, and the manifest next to it, need no build step
// at all to end up in the right place.
const CACHE_VERSION = "plant-care-v1";

const PRECACHE_URLS = ["/", "/manifest.webmanifest", "/icons/icon-192.svg", "/icons/icon-512.svg"];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE_VERSION)
      .then((cache) => cache.addAll(PRECACHE_URLS))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((key) => key !== CACHE_VERSION).map((key) => caches.delete(key))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Content-hashed build assets never change under the same filename —
  // cache-first is safe and keeps the app usable offline once visited.
  if (url.pathname.startsWith("/assets/")) {
    event.respondWith(
      caches.match(request).then(
        (cached) =>
          cached ??
          fetch(request).then((response) => {
            if (response.ok) caches.open(CACHE_VERSION).then((cache) => cache.put(request, response.clone()));
            return response;
          }),
      ),
    );
    return;
  }

  // Everything else (navigations, API calls) is network-first so users
  // always get fresh data when online, falling back to the last cached
  // shell only when offline.
  event.respondWith(
    fetch(request)
      .then((response) => {
        if (request.mode === "navigate" && response.ok) {
          caches.open(CACHE_VERSION).then((cache) => cache.put(request, response.clone()));
        }
        return response;
      })
      .catch(() => caches.match(request).then((cached) => cached ?? caches.match("/"))),
  );
});
